    # All lines were valid format-wise - now process according to rules
    return _process_valid_entries(valid_entries)


def _process_valid_entries(valid_entries: list) -> str:
    # Group entries by index while preserving file order
    index_entries = {}  # index -> list of (term, node, op, data)
    for entry in valid_entries:
        term, index, node, op, data = entry
        if index not in index_entries:
            index_entries[index] = []
        index_entries[index].append((term, node, op, data))

    violations = []  # list of (index, reason)
    repairs = []  # list of (term, index) for INS statements

    # Rule 1: Term Monotonicity - within each index, terms must be non-decreasing in file order
    for idx, entries in index_entries.items():
        prev_term = None
        for entry in entries:
            term = entry[0]
            if prev_term is not None and term < prev_term:
                violations.append((idx, "BAD_TERM_REGRESSION"))
            prev_term = term

    # Rule 3: Vote tracking - globally across all indices in file order
    node_votes_seen = {}  # node -> set of terms where votes have been seen
    for entry in valid_entries:  # file order
        term, index, node, op, data = entry
        if op == 'VOTE':
            if node not in node_votes_seen:
                node_votes_seen[node] = set()
            if term in node_votes_seen[node]:
                violations.append((index, "BAD_DUPLICATE_VOTE"))
            node_votes_seen[node].add(term)

    # Rule 3: Leader tracking - first LEADER index per term
    first_leader_index_by_term = {}  # term -> first index where LEADER appeared
    for entry in valid_entries:  # file order
        term, index, node, op, data = entry
        if op == 'LEADER':
            if term not in first_leader_index_by_term:
                first_leader_index_by_term[term] = index
            else:
                violations.append((index, "BAD_LEADER_ORDER"))

    # Determine which indices have APPEND entries and compute winning terms
    has_appends = {}  # index -> bool
    appends_at_index = {}  # index -> list of (term, node, data) for APPENDs in file order
    commit_exists = {}  # index -> bool
    commit_term = {}  # index -> term from COMMIT

    for idx, entries in index_entries.items():
        has_appends[idx] = False
        appends_at_index[idx] = []
        commit_exists[idx] = False
        commit_term[idx] = None

        for entry in entries:
            term, node, op, data = entry[0], entry[1], entry[2], entry[3]
            if op == 'APPEND':
                has_appends[idx] = True
                appends_at_index[idx].append((term, node, data))
            elif op == 'COMMIT':
                commit_exists[idx] = True
                commit_term[idx] = term

    # Determine winning term for each index with APPENDs
    winning_term_by_index = {}  # index -> winning term
    for idx in index_entries:
        if has_appends[idx]:
            appends = appends_at_index[idx]
            # Find highest term; tie-breaker is later file order (higher index in appends list)
            max_term = -1
            winning_file_idx = -1  # index in appends list where max was found
            for i, (term, node, data) in enumerate(appends):
                if term > max_term:
                    max_term = term
                    winning_file_idx = i
                elif term == max_term:
                    if i > winning_file_idx:
                        winning_file_idx = i
            winning_term_by_index[idx] = max_term
        else:
            winning_term_by_index[idx] = None

    # Check Rule 5: BAD_CONFLICT - same term different data among APPENDs at same index
    # Also add this to violations list
    for idx in index_entries:
        appends = appends_at_index[idx]
        term_data_map = {}  # term -> set of data values
        for term, node, data in appends:
            if term not in term_data_map:
                term_data_map[term] = set()
            term_data_map[term].add(data)
        has_conflict = False
        for term, data_set in term_data_map.items():
            if len(data_set) > 1:
                has_conflict = True
                break
        if has_conflict:
            violations.append((idx, "BAD_CONFLICT"))

    # Check Rule 4: BAD_COMMIT_ORDER
    # - COMMIT without preceding APPEND at same index
    # - COMMIT term must match winning APPEND term
    for idx in index_entries:
        if not has_appends[idx]:
            if commit_exists[idx]:
                violations.append((idx, "BAD_COMMIT_ORDER"))
        else:
            if not commit_exists[idx]:
                # Has APPEND but no COMMIT - not BAD_COMMIT_ORDER
                pass
            else:
                # Has COMMIT - check term match
                if commit_term[idx] != winning_term_by_index[idx]:
                    violations.append((idx, "BAD_COMMIT_ORDER"))

    # Check Rule 2: BAD_LOG_MATCH
    # For consecutive indices i and i+1 (by index number):
    # If index i has a committed entry (COMMIT) with term T, then index i+1 must have ALL entries with term >= T
    all_indices = sorted(index_entries.keys())  # sorted by index number
    for i in range(len(all_indices) - 1):
        idx_i = all_indices[i]
        idx_i1 = all_indices[i+1]
        if commit_exists[idx_i]:
            T = commit_term[idx_i]
            # Check all entries at idx_i+1
            entries_i1 = index_entries[idx_i1]
            for entry in entries_i1:
                term = entry[0]
                if term < T:
                    violations.append((idx_i1, "BAD_LOG_MATCH"))
                    break  # One violation is enough for this pair

    # Rule: BAD_OPERATION for unknown op types
    for entry in valid_entries:
        term, index, node, op, data = entry
        if op not in ['VOTE', 'APPEND', 'COMMIT', 'LEADER']:
            violations.append((index, "BAD_OPERATION"))

    # Generate repairs: indices with APPENDs but no COMMIT AND no violations at that index
    for idx in index_entries:
        if has_appends[idx] and not commit_exists[idx]:
            # Check if this index has any violations
            has_violation_at_idx = any(v[0] == idx for v in violations)
            if not has_violation_at_idx:
                term_to_insert = winning_term_by_index[idx]
                repairs.append((term_to_insert, idx))

    # Output formatting
    violations_sorted = sorted(violations, key=lambda x: x[0])
    repairs_sorted = sorted(repairs, key=lambda x: (x[1], x[0]))  # (index, term)

    lines_out = []
    for idx, reason in violations_sorted:
        lines_out.append(f"BAD {idx} {reason}")
    for term, idx in repairs_sorted:
        lines_out.append(f"INS {term} {idx} COMMIT")

    if not lines_out:
        return "OK"
    return "\n".join(lines_out)
EOF"}
